START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104150312_Phase4') THEN
    CREATE TABLE "Delivery_Platforms" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Source" character varying(60) NOT NULL,
        "DisplayName" character varying(120) NOT NULL,
        "IsActive" boolean NOT NULL,
        "StatusCallbackUrl" character varying(1000),
        "PriceMarkupPercent" numeric(9,2) NOT NULL,
        "AutoAccept" boolean NOT NULL,
        "MappedItemsOnly" boolean NOT NULL,
        "CreatedOn" timestamp with time zone NOT NULL,
        "CreatedBy" character varying(256) NOT NULL,
        CONSTRAINT "PK_Delivery_Platforms" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104150312_Phase4') THEN
    CREATE TABLE "Menu_ItemModels" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ItemId" integer NOT NULL,
        "GlbPath" character varying(500) NOT NULL,
        "UsdzPath" character varying(500),
        "PosterPath" character varying(500),
        "GlbBytes" bigint NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedOn" timestamp with time zone NOT NULL,
        "UpdatedOn" timestamp with time zone,
        "UpdatedBy" character varying(256) NOT NULL,
        CONSTRAINT "PK_Menu_ItemModels" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Menu_ItemModels_Items_ItemId" FOREIGN KEY ("ItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
