        "SuggestItemId" integer NOT NULL,
        "PairCount" integer NOT NULL,
        "Confidence" numeric(9,4) NOT NULL,
        "Lift" numeric(9,4) NOT NULL,
        "Pitch" character varying(200),
        "ComputedOn" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Upsell_Pairs" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Upsell_Pairs_Items_ItemId" FOREIGN KEY ("ItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Upsell_Pairs_Items_SuggestItemId" FOREIGN KEY ("SuggestItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE
