        "SuggestItemId" integer NOT NULL,
        "Message" character varying(200),
        "Priority" integer NOT NULL,
        "IsActive" boolean NOT NULL,
        "CreatedOn" timestamp with time zone NOT NULL,
        "CreatedBy" character varying(256) NOT NULL,
        CONSTRAINT "PK_Upsell_Rules" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Upsell_Rules_Categories_TriggerCategoryId" FOREIGN KEY ("TriggerCategoryId") REFERENCES "Categories" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Upsell_Rules_Items_SuggestItemId" FOREIGN KEY ("SuggestItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Upsell_Rules_Items_TriggerItemId" FOREIGN KEY ("TriggerItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE
