        "PlatformId" integer NOT NULL,
        "DeliveryOrderId" integer NOT NULL,
        "StatusEventId" integer NOT NULL,
        "ExternalRef" character varying(120) NOT NULL,
        "Status" character varying(30) NOT NULL,
        "State" character varying(10) NOT NULL,
        "Attempts" integer NOT NULL,
        "LastHttpStatus" integer,
        "LastError" character varying(1000),
        "CreatedOn" timestamp with time zone NOT NULL,
        "SentOn" timestamp with time zone,
        "NextAttemptOn" timestamp with time zone,
        CONSTRAINT "PK_Delivery_PlatformPushes" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Delivery_PlatformPushes_Delivery_Orders_DeliveryOrderId" FOREIGN KEY ("DeliveryOrderId") REFERENCES "Delivery_Orders" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Delivery_PlatformPushes_Delivery_Platforms_PlatformId" FOREIGN KEY ("PlatformId") REFERENCES "Delivery_Platforms" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261104150312_Phase4') THEN
    CREATE TABLE "Pay_TerminalPayments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TransactionId" integer NOT NULL,
        "TerminalId" integer NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "Currency" character varying(3) NOT NULL,
        "ExternalId" character varying(80) NOT NULL,
        "Status" character varying(20) NOT NULL,
        "ApprovalCode" character varying(20),
        "CardLast4" character varying(4),
        "CardScheme" character varying(20),
        "Rrn" character varying(40),
        "Message" character varying(300),
        "CreatedOn" timestamp with time zone NOT NULL,
        "CreatedBy" character varying(256) NOT NULL,
        "CompletedOn" timestamp with time zone,
        "LastCheckedOn" timestamp with time zone,
        "Raw" text,
        "BranchId" integer,
        CONSTRAINT "PK_Pay_TerminalPayments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Pay_TerminalPayments_Pay_CardTerminals_TerminalId" FOREIGN KEY ("TerminalId") REFERENCES "Pay_CardTerminals" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Pay_TerminalPayments_transactions_TransactionId" FOREIGN KEY ("TransactionId") REFERENCES transactions ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

